/**
 * @name Command injection via subprocess
 * @description Using subprocess with shell=True and untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description Using user-controlled paths without validation can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Command injection via filename in edit function
 * @description User-controlled filenames passed to edit() can lead to command injection via shell=True
 * @kind path-problem
 * @problem.severity error
 * @id py/click-edit-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EditCommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any parameter node that could be user-controlled
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true and
      sink = call.getArg(0)
    )
  }
}

module EditCommandInjectionFlow = TaintTracking::Global<EditCommandInjectionConfig>;
import EditCommandInjectionFlow::PathGraph

from EditCommandInjectionFlow::PathNode source, EditCommandInjectionFlow::PathNode sink
where EditCommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection via user-controlled input from $@.", source.getNode(), "parameter"

/**
 * @name Command injection in edit_files
 * @description Using subprocess with shell=True and user-controlled filenames can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/click-edit-files-command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EditFilesConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the filenames parameter of edit_files or edit function
    exists(DataFlow::ParameterNode param |
      param.getParameter().getName() in ["filenames", "filename"] and
      source = param
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the args parameter of subprocess.Popen with shell=True
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true and
      sink = call.getArg(0)
    )
  }
}

module EditFilesFlow = TaintTracking::Global<EditFilesConfig>;
