from EditFilesFlow::PathNode source, EditFilesFlow::PathNode sink
where EditFilesFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection via user-controlled filenames from $@.", source.getNode(), "parameter"

/**
 * @name Command injection in edit_files via filename
 * @description The edit_files function constructs a shell command with user-controlled filenames
 * @kind path-problem
 * @problem.severity error
 * @id py/click-edit-files-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EditFilesConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any parameter node could be user-controlled
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember("Popen").getACall() and
      call.getArg(0) = sink and
      // Check if shell=True is set
      exists(DataFlow::Node shellArg |
        shellArg = call.getArgByName("shell") and
        shellArg.asExpr().(BooleanLiteral).booleanValue() = true
      )
    )
  }
}

module EditFilesFlow = TaintTracking::Global<EditFilesConfig>;
import EditFilesFlow::PathGraph

from EditFilesFlow::PathNode source, EditFilesFlow::PathNode sink
where 
  EditFilesFlow::flowPath(source, sink) and
  sink.getNode().getLocation().getFile().getBaseName() = "_termui_impl.py"
select sink.getNode(), source, sink, "Command injection via user-controlled input from $@.", source.getNode(), "parameter"

/**
 * @name Command injection in edit_files via editor parameter
 * @description Using subprocess with shell=True and user-controlled editor or filenames can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/click-edit-files-editor-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EditFilesInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param |
      param.getParameter().getName() in ["editor", "filenames", "filename"] and
      source = param
    )
